pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        admin = msg.sender;
        c = new C();
    }

    function testFuzz_property(address newOwner, address previousOwner) public {
        // Keep the domain wide: only exclude the zero address as a candidate owner
        // (assigning it is still admissible, but we keep the search space broad).
        vm.assume(newOwner != address(0));

        // Establish a known previous owner distinct from the candidate so that
        // P and M's return values can be told apart when the mutant evaluates
        // the return expression against a stale/other owner.
        vm.assume(previousOwner != newOwner);
        vm.prank(admin);
        c.setOwner(previousOwner);

        // Drive c through setOwner as the admin; capture the declared success
        // flag via the public boundary (try/catch over the external call).
        bool ok;
        vm.prank(admin);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // General rule: a successful owner update performed by the admin must
        // always report success == true, regardless of whether the new owner
        // equals the previously stored owner.
        assertTrue(ok, "setOwner by admin must report success for any new owner");
    }
}

